// Scenario router (generated by scripts/build-cpts.mjs). Without scripts the page
// is the whole playbook: every situation is an expandable <details>. This adds
// the page chrome (Ctrl+K, header, theme, hero), copy buttons on the command
// blocks, and a search that filters the plays and rolls up to the groups.
import { initCommandPalette } from "../../js/command-palette.js?v=search2";
import { initSiteHeader } from "../../js/site-header.js?v=276fa973-header";
import { initTheme } from "../../js/theme.js?v=276fa973";
import { initHeroDither } from "../../js/hero-dither.js?v=276fa973-idle";
import { copyTextToClipboard } from "../../js/markdown.js?v=276fa973-th";

const addCopy = (pre) => {
  if (pre.parentElement?.classList.contains("sc-cmd-wrap")) return;
  const wrap = document.createElement("div");
  wrap.className = "sc-cmd-wrap";
  pre.before(wrap);
  wrap.append(pre);
  const btn = document.createElement("button");
  btn.type = "button";
  btn.className = "sc-copy";
  btn.textContent = "Copy";
  btn.addEventListener("click", () => {
    const text = (pre.querySelector("code")?.textContent || "").trim();
    void copyTextToClipboard(text, btn, "Copy");
  });
  wrap.append(btn);
};

const initSearch = () => {
  const input = document.getElementById("sc-q");
  if (!input) return;
  const count = document.getElementById("sc-count");
  const empty = document.getElementById("sc-empty");
  const items = [...document.querySelectorAll(".sc-item")];
  const groups = [...document.querySelectorAll(".sc-group")];
  const total = count ? count.textContent : "";

  const apply = () => {
    const q = input.value.trim().toLowerCase();
    let shown = 0;
    for (const item of items) {
      const match = !q || (item.dataset.search || "").includes(q);
      item.hidden = !match;
      if (match) shown += 1;
    }
    for (const group of groups) {
      const any = [...group.querySelectorAll(".sc-item")].some((i) => !i.hidden);
      group.hidden = !any;
    }
    if (count) count.textContent = q ? `${shown} match${shown === 1 ? "" : "es"}` : total;
    if (empty) empty.hidden = shown > 0 || !q;
  };

  input.addEventListener("input", apply);
  apply();
};

document.addEventListener("DOMContentLoaded", () => {
  initCommandPalette();
  initSiteHeader();
  initTheme();
  initHeroDither();
  for (const pre of document.querySelectorAll(".sc-cmd")) addCopy(pre);
  initSearch();
});
